mapper.select:
select count(*) from mall_home_content
where del_flag = '0' and status = 'PUBLISHED' and content_type = #{contentType}
  and (#{contentId} is null or content_id <> #{contentId})
  and effective_time < coalesce(#{expireTime}, '9999-12-31 23:59:59')
  and coalesce(expire_time, '9999-12-31 23:59:59') > #{effectiveTime}
